<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Country</title><link rel='stylesheet' href='/styles.css'><link rel='stylesheet' href='https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css'></head><body><div class='page'><div id='content' class='card'>Loading...</div></div><script src='/ui.js'></script><script>
GameUI.mountShell('');
(async()=>{const id=Number(location.pathname.split('/').pop()||0); if(!id)return content.textContent='Invalid country id'; try{const c=await GameUI.api('/api/map/country-detail?id='+id); content.innerHTML=`<h2>${c.country_name||c.name}</h2><p class='muted'>${c.government_type||''}</p><div class='grid cards'><div class='card'><b>Total Regions</b><div>${c.region_count||0}</div></div><div class='card'><b>Treasury</b><div>${GameUI.fmt(c.treasury_state_money)}</div></div><div class='card'><b>Gold</b><div>${GameUI.fmt(c.treasury_gold)}</div></div></div><h3>Regions</h3><div class='list'>${(c.regions||[]).map(r=>`<a class='list-row' href='/region/${r.id}'><span>${r.name}</span><span>${GameUI.fmt((r.airport_count||0)+(r.army_count||0)+(r.hospital_count||0)+(r.education_count||0)+(r.port_count||0))}</span></a>`).join('')}</div>`;}catch(e){content.textContent=e.message}})();
</script></body></html>
